package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamStateOrgBank2 {
  private const val T = "ව්‍යවස්ථාදායකය, විධායකය හා අධිකරණ ව්‍යුහය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ශ්‍රී ලංකාවේ විධායක ජනාධිපතිවරයෙකු තෝරාපත් කරගැනීම සඳහා පුරවැසියෙකු සපුරා තිබිය යුතු මූලික සුදුසුකමක් වන්නේ කුමක්ද?", "උපතින් හෝ පරම්පරාවෙන් ශ්‍රී ලංකා පුරවැසියෙකු වීම හා අවුරුදු 30 හෝ 35 සම්පූර්ණ වීම", "රජයේ විගණකාධිපති ධුරය දරා තිබීම", "පළාත් සභා සභාපතිවරයෙකු වී සිටීම", "ද්විත්ව පුරවැසිභාවය දැරීම", "ද්විත්ව පුරවැසියන්ට හා දෙවරක් ධුරය දැරූ අයට ජනාධිපති ධුරයට තරග කළ නොහැක."),
    q("රටේ පාර්ලිමේන්තුව විසින් අමාත්‍ය මණ්ඩලය කෙරෙහි 'විශ්වාසභංග යෝජනාවක්' සම්මත කළ විට ඇතිවන ව්‍යවස්ථාපිත ප්‍රතිඵලය කුමක්ද?", "කැබිනට් මණ්ඩලය විසුරුවී අග්‍රාමාත්‍යවරයාට ධුරය අහිමි වීම", "ජනාධිපති ධුරය ස්වයංක්‍රීයව අහෝසි වීම", "ශ්‍රේෂ්ඨාධිකරණය විසුරුවා හැරීම", "පළාත් සභා නවයම අහෝසි වීම", "48(2) වගන්තිය අනුව රජය කෙරෙහි විශ්වාසභංග යෝජනාවක් සම්මත වීමෙන් කැබිනට්ටුව විසුරුවී යයි."),
    q("පාර්ලිමේන්තු මැතිවරණයකින් පසු ජනාධිපතිවරයා විසින් කැබිනට් මණ්ඩලයේ අමාත්‍යාංශ විෂයයන් බෙදා දීම සිදු කරන්නේ කෙසේද?", "ගැසට් නිවේදනයක් මඟින් විෂයයන් හා කාර්යයන් පැවරීමෙන්", "පළාත් සභාවල අනුමැතිය ලබාගෙන", "සමථ මණ්ඩලවල නිර්දේශ මත", "දිසා අධිකරණ නියෝගයකින්", "ජනාධිපතිවරයා අතිවිශේෂ ගැසට් නිවේදනයකින් අමාත්‍යාංශ හා විෂයයන් ප්‍රකාශයට පත් කරයි."),
    q("ශ්‍රී ලංකාවේ නීති සම්පාදන ක්‍රියාවලියේදී 'පෞද්ගලික මන්ත්‍රී පනත් කෙටුම්පතක්' (Private Member's Bill) යනු කුමක්ද?", "කැබිනට් අමාත්‍යවරයෙකු නොවන පාර්ලිමේන්තු මන්ත්‍රීවරයෙකු ඉදිරිපත් කරන කෙටුම්පතක්", "පෞද්ගලික සමාගමක් සකසන ව්‍යවස්ථාවක්", "මහේස්ත්‍රාත්වරයෙකු නිකුත් කරන වරෙන්තුවක්", "විදේශ තානාපතිවරයෙකු ගෙන එන ගිවිසුමක්", "ආණ්ඩු පක්ෂයේ හෝ විපක්ෂයේ සාමාන්‍ය මන්ත්‍රීවරයෙකුටද පනත් කෙටුම්පත් ඉදිරිපත් කළ හැක."),
    q("පාර්ලිමේන්තුවේ 'කාරක සභා' පිහිටුවීමෙන් නීති සම්පාදන ක්‍රියාවලියට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "ගැඹුරු විශේෂඥ පරීක්ෂාවක් හා කාලය ඉතිරි කරගනිමින් කරුණු සොයාබැලීමට හැකි වීම", "මන්ත්‍රීවරුන්ගේ ඡන්ද අයිතිය අහෝසි කිරීම", "මහජනතාවගෙන් බදු අය කිරීම නතර කිරීම", "විපක්ෂයට කතා කිරීම තහනම් කිරීම", "සමස්ත සභාවේ කාලය සීමිත බැවින් කාරක සභා හරහා සවිස්තරාත්මක විමර්ශන කෙරේ."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තුවේ 'වරප්‍රසාද පිළිබඳ කාරක සභාවේ' ප්‍රධාන කාර්යභාරය කුමක්ද?", "පාර්ලිමේන්තුවේ හා මන්ත්‍රීවරුන්ගේ වරප්‍රසාද කඩවීම් පිළිබඳ පැමිණිලි විමර්ශනය කිරීම", "රාජ්‍ය බැංකුවල පොලී අනුපාත නියම කිරීම", "විශ්වවිද්‍යාල ආචාර්යවරුන් බඳවා ගැනීම", "පළාත් පාලන මැතිවරණ පැවැත්වීම", "මන්ත්‍රීවරුන්ගේ වරප්‍රසාද හා ගෞරවය ආරක්ෂා කිරීම මෙම කමිටුවේ වගකීමයි."),
    q("පාර්ලිමේන්තුව විසින් අනුමත කරන ලද මුදල් රජයේ වියදම් සඳහා තැන්පත් කර ඇති ප්‍රධාන රාජ්‍ය අරමුදල කුමක්ද?", "ඒකාබද්ධ අරමුදල", "සේවක අර්ථසාධක අරමුදල", "රක්ෂණ සංස්ථා අරමුදල", "පළාත් සභා සමථ අරමුදල", "149 වන වගන්තිය අනුව රජයේ සියලු ආදායම් ඒකාබද්ධ අරමුදලට (Consolidated Fund) බැර වේ."),
    q("රජයේ ප්‍රතිපත්ති පිළිබඳව අමාත්‍යාංශ විෂයයන් සමාලෝචනය කිරීමට පිහිටුවන ලද උපදේශක මණ්ඩල කවරේද?", "අමාත්‍යාංශයීය උපදේශක කාරක සභා", "මහේස්ත්‍රාත් උපදේශක සභා", "සමථ මණ්ඩල සංගම්", "විදේශ වෙළඳ මණ්ඩල", "සෑම අමාත්‍යාංශයක්ම ආවරණය වන පරිදි පාර්ලිමේන්තුවේ අමාත්‍යාංශයීය උපදේශක කාරක සභා පවතී."),
    q("විධායක ජනාධිපතිවරයාට පාර්ලිමේන්තුව 'වාරාවසාන කිරීම' (Prorogation) මඟින් සිදු වන්නේ කුමක්ද?", "පවතින සැසිවාරය අවසන් කර නව සැසිවාරයක් සඳහා දින නියම කිරීම", "සියලු මන්ත්‍රීවරුන්ගේ ධුර සම්පූර්ණයෙන් අහෝසි කිරීම", "මහ මැතිවරණයක් කැඳවීම", "ව්‍යවස්ථාව සම්පූර්ණයෙන් අවලංගු කිරීම", "වාරාවසාන කිරීමේදී මන්ත්‍රී ධුර අහෝසි නොවී සැසිවාරය පමණක් අවසන් කෙරේ."),
    q("පාර්ලිමේන්තුව 'විසුරුවා හැරීම' (Dissolution) සහ 'වාරාවසාන කිරීම' අතර ප්‍රධාන වෙනස කුමක්ද?", "විසුරුවා හැරීමේදී මහ මැතිවරණයක් කැඳවන නමුත් වාරාවසාන කිරීමේදී එසේ නොවේ", "වාරාවසාන කිරීමේදී ජනාධිපති ධුරය අහෝසි වේ", "විසුරුවා හැරීමේදී මන්ත්‍රීවරුන් සදාකාලිකව තනතුරේ සිටී", "දෙකෙන්ම සිදුවන්නේ එකම ක්‍රියාවකි", "විසුරුවා හැරීමෙන් මන්ත්‍රී ධුර අවසන් වී නව මහ මැතිවරණයක් පැවැත්වේ."),
    q("විධායකය ව්‍යවස්ථාදායකයෙන් වෙන්ව ඇති ඇමරිකානු ජනාධිපති ක්‍රමයේ මැති ඇමතිවරුන් පත් කිරීමේ විශේෂත්වය කුමක්ද?", "ඇමතිවරුන් කොංග්‍රස් මණ්ඩලයේ සාමාජිකයන් නොවීම", "ඇමතිවරුන් සැමවිටම සෙනෙට් සභිකයන් වීම", "අගමැතිවරයෙකු අනිවාර්යයෙන් සිටීම", "ඇමතිවරුන් නොමැතිව ජනාධිපති තනිව පාලනය කිරීම", "ඇමරිකාවේ දැඩි බලතල බෙදීම නිසා විධායක ලේකම්වරුන් ව්‍යවස්ථාදායකයේ නොසිටිති."),
    q("ශ්‍රී ලංකාවේ කැබිනට් අමාත්‍යවරුන් අනිවාර්යයෙන්ම කවුරුන් විය යුතුද?", "පාර්ලිමේන්තු මන්ත්‍රීවරුන්", "ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන්", "පළාත් ආණ්ඩුකාරවරුන්", "හමුදාපතිවරුන්", "ශ්‍රී ලංකාවේ අර්ධ-ජනාධිපති ක්‍රමය යටතේ සියලු කැබිනට් ඇමතිවරුන් පාර්ලිමේන්තු මන්ත්‍රීවරුන් වේ."),
    q("රටේ පවතින යම් සිදුවීමක් හෝ පරිපාලන අක්‍රමිකතාවක් ගැන කරුණු සෙවීමට ජනාධිපතිවරයා විසින් පත් කරනු ලබන විශේෂ කොමිසම කුමක්ද?", "ජනාධිපති පරීක්ෂණ කොමිෂන් සභාව", "ගම්සභා අධිකරණය", "සමථ මණ්ඩලය", "මහා භාණ්ඩාගාර කමිටුව", "ජාතික වැදගත්කමක් ඇති කරුණු විමර්ශනයට ජනාධිපතිවරයාට පරීක්ෂණ කොමිෂන් පත් කළ හැක."),
    q("විධායකයේ තීරණ අධිකරණයකදී අවලංගු කළ හැකි 'අධිකරණ සමාලෝචනය' (Judicial Review) මඟින් ආරක්ෂා වන්නේ කුමක්ද?", "පුරවැසි අයිතිවාසිකම් හා ව්‍යවස්ථානුකූලභාවය", "විධායකයේ අත්තනෝමතික බලය", "පාර්ලිමේන්තු වරප්‍රසාද උල්ලංඝනය", "ඒකාධිපති පාලනය", "නීතියට පටහැනි විධායක හා පරිපාලන ක්‍රියා අධිකරණයට අභියෝග කළ හැක."),
    q("රජයේ පරිපාලන ආයතනයක නිලධාරියෙකු තම නීත්‍යානුකූල රාජකාරිය ඉටු කිරීම පැහැර හරින විට එය ඉටු කරන ලෙස අභියාචනාධිකරණය නිකුත් කරන ආඥාව කුමක්ද?", "මැන්ඩමුස් ආඥාව", "හබයාස් කෝපස් ආඥාව", "සර්ටියෝරාරි ආඥාව", "කුවෝ වොරන්ටෝ ආඥාව", "රාජ්‍ය බලධාරියෙකු ලවා නෛතික යුතුකම ඉටු කරවීමට Mandamus රිට් ආඥාව නිකුත් කෙරේ."),
    q("පහළ අධිකරණයක් හෝ විනිශ්චය මණ්ඩලයක් සිය බල සීමාව ඉක්මවා දුන් තීරණයක් බලරහිත කිරීමට නිකුත් කරන රිට් ආඥාව කුමක්ද?", "සර්ටියෝරාරි ආඥාව", "හබයාස් කෝපස් ආඥාව", "මැන්ඩමුස් ආඥාව", "ජස් සෝලි ආඥාව", "Certiorari රිට් ආඥාව මඟින් නීති විරෝධී පරිපාලන හා අධිකරණ තීරණ අවලංගු කෙරේ."),
    q("යම් පුද්ගලයෙකු නීත්‍යානුකූල හිමිකමක් නොමැතිව රාජ්‍ය තනතුරක් දරන්නේ නම් ඔහුගේ බලය ප්‍රශ්න කරමින් නිකුත් කරන රිට් ආඥාව කුමක්ද?", "කුවෝ වොරන්ටෝ ආඥාව", "මැන්ඩමුස් ආඥාව", "හබයාස් කෝපස් ආඥාව", "තහනම් ආඥාව", "Quo Warranto යනු 'කවර බලයකින්ද?' යන්න විමසමින් අනවසර තනතුරු දැරීම වැළැක්වීමේ ආඥාවයි."),
    q("පහළ විනිශ්චය මණ්ඩලයක් තම බල සීමාව ඉක්මවා කටයුතු කිරීමට සූදානම් වන විට එය කලින්ම වළක්වා ගැනීමට නිකුත් කරන රිට් ආඥාව කුමක්ද?", "තහනම් ආඥාව (Prohibition)", "මැන්ඩමුස් ආඥාව", "සර්ටියෝරාරි ආඥාව", "හබයාස් කෝපස් ආඥාව", "Prohibition ආඥාව අධිකරණ බල සීමා ඉක්මවීම කලින්ම අත්හිටුවයි."),
    q("අපරාධ නඩු විභාගයකදී 'ජූරි සභාවක්' (Jury) සහභාගී කරවා ගනු ලබන්නේ කුමන අධිකරණයේදීද?", "මහාධිකරණයේදී", "ප්‍රාථමික අධිකරණයේදී", "දිසා අධිකරණයේදී", "සමථ මණ්ඩලයේදී", "චූදිතයා ඉල්ලා සිටින බරපතළ අපරාධ නඩු මහාධිකරණයේදී ජූරි සභාවක් ඉදිරියේ විභාග කෙරේ."),
    q("අධිකරණ ශාලාව තුළ සාධාරණ නඩු විභාගයක් පැවැත්වීමේදී පැමිණිලි පාර්ශ්වයට මෙන්ම විත්ති පාර්ශ්වයටත් සවන් දීමේ මූලධර්මය කුමක්ද?", "ස්වාභාවික යුක්ති මූලධර්මය", "පාර්ලිමේන්තු මුක්ති මූලධර්මය", "විධායක අභිමතය", "රාජ්‍ය රහස්‍යභාවය", "දෙපාර්ශ්වයටම සවන් දීම (Audi alteram partem) ස්වාභාවික යුක්තියේ ප්‍රධාන අංගයකි."),
    q("විනිසුරුවරයෙකු තමාට පෞද්ගලික සම්බන්ධතාවක් හෝ පෞද්ගලික වාසියක් ඇති නඩුවක් විභාග නොකර ඉවත් විය යුත්තේ කුමන මූලධර්මය අනුවද?", "ස්වාභාවික යුක්ති මූලධර්මයේ අපක්ෂපාතීත්වය", "රාජ්‍ය සේවා මධ්‍යගතකරණය", "සාමූහික කැබිනට් වගකීම", "බහුතර මනාප නීතිය", "කිසිවෙකු තමන්ගේම නඩුවේ විනිසුරු නොවිය යුතුය (Nemo judex in causa sua)."),
    q("ශ්‍රී ලංකාවේ ශ්‍රේෂ්ඨාධිකරණයේ අගවිනිසුරුවරයා ඇතුළුව සිටිය හැකි විනිසුරුවරුන්ගේ ප්‍රමාණය ව්‍යවස්ථාවෙන් නියම කර ඇති ආකාරය කුමක්ද?", "අගවිනිසුරුවරයා සහ තවත් විනිසුරුවරුන් 6ත් 17ත් අතර සංඛ්‍යාවක්", "එක් විනිසුරුවරයෙකු පමණි", "විනිසුරුවරුන් 225 දෙනෙකු", "විනිසුරුවරුන් 50 දෙනෙකු", "20 වන සංශෝධනයෙන් පසු අගවිනිසුරු සමඟ ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන් සංඛ්‍යාව 17 දක්වා පුළුල් කෙරිණි."),
    q("ව්‍යවස්ථාව අනුව යම් නීති ප්‍රශ්නයක් සම්බන්ධයෙන් ජනාධිපතිවරයාට ශ්‍රේෂ්ඨාධිකරණයේ උපදේශාත්මක මතය (Advisory Opinion) විමසිය හැකිද?", "ඔව්; 129 වන වගන්තිය යටතේ මතය විමසිය හැක", "නැත; එය සම්පූර්ණයෙන් තහනම්ය", "ඔව්; මහේස්ත්‍රාත් අධිකරණයෙන් පමණි", "ඔව්; වසර 10කට වරක් පමණි", "129 වන වගන්තිය අනුව ජාතික වැදගත්කමක් ඇති නීති ප්‍රශ්න පිළිබඳ ශ්‍රේෂ්ඨාධිකරණ මතය විමසිය හැක."),
    q("ශ්‍රී ලංකාවේ මැතිවරණ පෙත්සම් හා ජනාධිපතිවරණ පෙත්සම් විභාග කිරීමේ අධිකරණ බලය පැවරී ඇත්තේ කුමන අධිකරණවලටද?", "ශ්‍රේෂ්ඨාධිකරණයට හා අභියාචනාධිකරණයට", "සමථ මණ්ඩලවලට", "කම්කරු විනිශ්චය සභාවලට", "ප්‍රාථමික අධිකරණවලට", "ජනාධිපතිවරණ පෙත්සම් ශ්‍රේෂ්ඨාධිකරණයත්, පාර්ලිමේන්තු මැතිවරණ පෙත්සම් අභියාචනාධිකරණයත් විභාග කරයි."),
    q("රටේ පොදු පාරිභෝගික ආරක්ෂාව හා වාණිජ ආරවුල් විසඳීම සඳහා ශ්‍රී ලංකාවේ පිහිටුවා ඇති විශේෂිත අධිකරණය කුමක්ද?", "වාණිජ මහාධිකරණය", "යුද අධිකරණය", "කම්කරු අධිකරණය", "ප්‍රාථමික අධිකරණය", "විශාල වටිනාකමකින් යුත් වාණිජ ආරවුල් කඩිනමින් විසඳීමට වාණිජ මහාධිකරණ පිහිටුවා ඇත."),
    q("ශ්‍රී ලංකාවේ 'අධිකරණ නිලධාරීන් හා නීතිඥවරුන්' අතර වෘත්තීය විනය පාලනය හා නීති අධ්‍යාපනය සඳහා ප්‍රධාන වන ආයතන මොනවාද?", "ශ්‍රී ලංකා නීති විද්‍යාලය හා ශ්‍රේෂ්ඨාධිකරණය", "මැතිවරණ කොමිසම හා පොලිසිය", "විගණන සේවා කොමිසම හා මහ බැංකුව", "පළාත් සභා හා නගර සභා", "නීතිඥවරුන් බඳවා ගැනීම හා විනය පාලනය ශ්‍රේෂ්ඨාධිකරණය යටතේ සිදු කෙරේ."),
    q("රටේ සාමය හා පොදු ආරක්ෂාව පවත්වා ගෙන යාම සඳහා විධායකය යටතේ ක්‍රියාත්මක වන ප්‍රධාන සිවිල් නීති බලාත්මක කිරීමේ ආයතනය කුමක්ද?", "ශ්‍රී ලංකා පොලිස් දෙපාර්තමේන්තුව", "විගණකාධිපති දෙපාර්තමේන්තුව", "රජයේ රස පරීක්ෂක දෙපාර්තමේන්තුව", "ජාතික ලේඛනාරක්ෂක දෙපාර්තමේන්තුව", "අපරාධ වැළැක්වීම හා නීතිය ක්‍රියාත්මක කිරීම පොලිස් දෙපාර්තමේන්තුව මඟින් ඉටු කෙරේ."),
    q("විධායකය විසින් පාර්ලිමේන්තුවේ අනුමැතියකින් තොරව නව බද්දක් පැනවිය හැකිද?", "නැත; බදු පැනවීමේ බලය හිමිවන්නේ පාර්ලිමේන්තුවට පමණි", "ඔව්; ජනාධිපතිට තනිව පැනවිය හැක", "ඔව්; දිසාපතිවරයාට පැනවිය හැක", "ඔව්; පොලිස්පතිට පැනවිය හැක", "ව්‍යවස්ථාවේ 148 වගන්තිය අනුව පාර්ලිමේන්තු පනතකින් තොරව කිසිදු බද්දක් පැනවිය නොහැක."),
    q("රටේ වාර්ෂික අයවැය විවාදයේදී කැබිනට් අමාත්‍යාංශවල වැය ශීර්ෂ විවාද කරනු ලබන්නේ කුමන අදියරේදීද?", "කාරක සභා අවස්ථාවේදී", "පළමු කියවීමේදී", "නඩු විභාගයේදී", "ජනමත විචාරණයේදී", "අයවැය දෙවන වර කියවීමේ ඡන්දයෙන් පසු එක් එක් අමාත්‍යාංශයේ වැය ශීර්ෂ කාරක සභා අවස්ථාවේ විවාද කෙරේ."),
    q("අයවැය ඉදිරිපත් කරන දින සිට නව මුදල් වර්ෂයේ අයවැය සම්මත වන තෙක් අත්‍යවශ්‍ය වියදම් පියවීමට සම්මත කරගන්නා ගිණුම කුමක්ද?", "අතුරු සම්මත ගිණුම (Vote on Account)", "විගණන අතිරේක ගිණුම", "සමථ වන්දි ගිණුම", "පළාත් ආදායම් ගිණුම", "පූර්ණ අයවැයක් සම්මත වීමට පෙර කෙටි කාලීන රජයේ වියදම් සඳහා අතුරු සම්මත ගිණුම ඉදිරිපත් කෙරේ."),
    q("රාජ්‍ය ආයතනයක් පාර්ලිමේන්තුව අනුමත කළ මුදලට වඩා අමතර වියදමක් කිරීමට අවශ්‍ය වූ විට ඉදිරිපත් කරන්නේ කුමක්ද?", "පරිපූරක ඇස්තමේන්තුවක් (Supplementary Estimate)", "හදිසි නීති ආඥාවක්", "දෝෂාභියෝග යෝජනාවක්", "මැතිවරණ පෙත්සමක්", "අමතර මූල්‍ය ප්‍රතිපාදන සඳහා පරිපූරක ඇස්තමේන්තු පාර්ලිමේන්තු අනුමැතියට ගෙන එනු ලැබේ."),
    q("පාර්ලිමේන්තු කථානායකවරයාගේ තීරණවල මූලික ලක්ෂණය විය යුත්තේ කුමක්ද?", "පක්ෂ භේදයකින් තොරව අපක්ෂපාතීව හා සාධාරණව ක්‍රියා කිරීම", "ආණ්ඩු පක්ෂයට පමණක් කතා කිරීමට ඉඩ දීම", "විපක්ෂයේ සියලු මන්ත්‍රීවරුන් ඉවත් කිරීම", "හංසඩ් වාර්තා පළ කිරීම නැවැත්වීම", "කථානායකවරයා සභාවේ සියලු පක්ෂවල අයිතීන් සමානව ආරක්ෂා කළ යුතුය."),
    q("පාර්ලිමේන්තු කාරක සභාවලදී සාමාන්‍යයෙන් කෝප් (COPE) හා කෝපා (COPA) කමිටු රැස්වීම් මාධ්‍යයට විවෘත කිරීමෙන් ලැබෙන ප්‍රතිලාභය කුමක්ද?", "රාජ්‍ය මූල්‍ය පරිපාලනය පිළිබඳ මහජන විනිවිදභාවය වැඩි වීම", "රාජ්‍ය නිලධාරීන්ට වැටුප් නොගෙවීම", "විගණකාධිපති තනතුර අහෝසි වීම", "පනත් සම්මත වීම නතර වීම", "මහජන බදු මුදල් වැය කරන ආකාරය ජනතාවට සෘජුව දැකබලා ගැනීමට හැකි වේ."),
    q("ශ්‍රී ලංකාවේ 'අධිකරණයේ ගෞරවය' රැකගැනීම සඳහා නඩු තීන්දුවක් ප්‍රසිද්ධියේ විවේචනය කිරීම හෝ නඩුවට බලපෑම් කිරීම කවර වරදක්ද?", "අධිකරණයට අපහාස කිරීම", "පාර්ලිමේන්තු වරප්‍රසාද භාවිතය", "සමථකරණය", "පාරිභෝගික අයිතිය", "105(3) වගන්තිය අනුව අධිකරණයට අපහාස කිරීම (Contempt of Court) දඬුවම් ලැබිය හැකි වරදකි."),
    q("විධායකය විසින් පනවනු ලබන නීතිරීති හෝ ගැසට් නිවේදන පාර්ලිමේන්තුවේ අනුමැතිය සඳහා ඉදිරිපත් කිරීමෙන් සිදුවන්නේ කුමක්ද?", "විධායකය පාර්ලිමේන්තුවට වගකිව යුතු බව තහවුරු වීම", "අධිකරණ පද්ධතිය අහෝසි වීම", "පළාත් සභා නිල කාලය දීර්ඝ වීම", "ජනමත විචාරණ නතර වීම", "හදිසි නීති හා රෙගුලාසි ව්‍යවස්ථාදායකයේ පාලනයට යටත් කිරීම ප්‍රජාතන්ත්‍රවාදී පාලනයක ලක්ෂණයකි."),
    q("රටේ පාර්ලිමේන්තුවේ 'සභාව කල් තැබීමේ විවාදය' (Adjournment Debate) යනු කුමක්ද?", "දෛනික වැඩකටයුතු අවසානයේ විපක්ෂයට හා මන්ත්‍රීවරුන්ට මහජන ගැටලු ඉදිරිපත් කිරීමට දෙන අවස්ථාව", "පාර්ලිමේන්තුව වසර 5 කට විසුරුවා හැරීම", "කැබිනට් මණ්ඩලය ඉල්ලා අස්වීම", "විනිසුරුවරුන් පත් කිරීමේ උත්සවය", "මහජන ප්‍රශ්න ඇමතිවරුන්ගේ අවධානයට යොමු කිරීමට මෙම විවාදය යොදා ගැනේ."),
    q("පාර්ලිමේන්තුවේදී යම් පනත් කෙටුම්පතක් සම්බන්ධයෙන් 'අංග සම්පූර්ණ විමසීමක්' කිරීමට එය ජනතාවගේ අදහස් ලබාගැනීමට පළ කරන මූලාශ්‍රය කුමක්ද?", "රජයේ ගැසට් පත්‍රය", "පෞද්ගලික වෙළඳ දැන්වීම්", "පාසල් පෙළපොත්", "සමථ වාර්තා", "පනත් කෙටුම්පතක් සභාගත කිරීමට පෙර ගැසට් පත්‍රයේ පළ කර පුරවැසියන්ට දැනගැනීමට සලස්වයි."),
    q("පළාත් මට්ටමින් නීති සම්පාදනය කිරීමට පළාත් සභාවකට බලය හිමි වුවද එය ජාතික පාර්ලිමේන්තු බලයෙන් වෙනස් වන්නේ කෙසේද?", "පළාත් සභා ප්‍රඥප්ති පළාත් සභා ලැයිස්තුවට සීමා වන අතර ජාතික පාර්ලිමේන්තුවට ඉහළින් නොසිටීම", "පළාත් සභාවට විදේශ ගිවිසුම් අත්සන් කළ හැකි වීම", "පාර්ලිමේන්තුවට වඩා පළාත් සභාව බලවත් වීම", "පළාත් සභාව අධිකරණ තීන්දු අවලංගු කිරීම", "ඒකීය රාජ්‍ය ව්‍යුහය තුළ පාර්ලිමේන්තුව උත්තරීතර ව්‍යවස්ථාදායකය වේ."),
    q("1978 ව්‍යවස්ථාවේ 'ආණ්ඩුක්‍රම ව්‍යවස්ථාව සංශෝධනය කිරීමේ පනත් කෙටුම්පතක්' සාමාන්‍ය පනතකින් වෙනස් වන ලක්ෂණය කුමක්ද?", "සම්මත කිරීමට අවම 2/3 ක විශේෂ බහුතරයක් අවශ්‍ය වීම", "සරල බහුතරයකින්ම සම්මත කළ හැකි වීම", "ගැසට් පත්‍රයේ පළ කිරීම අනවශ්‍ය වීම", "කථානායක අත්සන අවශ්‍ය නොවීම", "ව්‍යවස්ථා සංශෝධනයක් සඳහා පාර්ලිමේන්තුවේ මුළු මන්ත්‍රී සංඛ්‍යාවෙන් තුනෙන් දෙකක ඡන්දය අනිවාර්ය වේ."),
    q("ශ්‍රී ලංකාවේ 'අධිකරණ සේවා කොමිෂන් සභාවේ' ස්වාභාවික සභාපතිවරයා ලෙස ක්‍රියා කරන්නේ කවුද?", "අගවිනිසුරුවරයා", "විධායක ජනාධිපතිවරයා", "අධිකරණ අමාත්‍යවරයා", "පාර්ලිමේන්තු කථානායක", "111ඈ වගන්තිය අනුව අගවිනිසුරුවරයා සහ ජ්‍යෙෂ්ඨ ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන් දෙදෙනෙකු මීට අයත් වේ."),
    q("අපරාධ නඩුවකදී පොලිසිය මඟින් අත්අඩංගුවට ගත් සැකකරුවෙකු පැය 24 ක් ඇතුළත ඉදිරිපත් කළ යුත්තේ කවරෙකු හමුවටද?", "මහේස්ත්‍රාත්වරයා හමුවට", "දිස්ත්‍රික් ලේකම්වරයා හමුවට", "පළාත් ආණ්ඩුකාරවරයා හමුවට", "නගරාධිපතිවරයා හමුවට", "අපරාධ නඩු විධාන සංග්‍රහය අනුව පැය 24 ක් ඇතුළත සැකකරුවෙකු මහේස්ත්‍රාත්වරයෙකුට ඉදිරිපත් කළ යුතුය."),
    q("විධායකයේ තීරණ ගැනීමේදී අමාත්‍ය මණ්ඩලයට තාක්ෂණික හා පරිපාලන උපදෙස් සපයනු ලබන්නේ කවුරුන් විසින්ද?", "අමාත්‍යාංශ ලේකම්වරුන් හා රාජ්‍ය නිලධාරීන් විසින්", "පාර්ලිමේන්තු විපක්ෂය විසින්", "මහේස්ත්‍රාත්වරුන් විසින්", "මැතිවරණ නිරීක්ෂකයන් විසින්", "රාජ්‍ය ප්‍රතිපත්ති සම්පාදනයේදී හා ක්‍රියාත්මක කිරීමේදී ස්ථිර රාජ්‍ය සේවය වෘත්තීය සහාය ලබාදේ."),
    q("ශ්‍රී ලංකාවේ දිසා අධිකරණයකදී සිදුවන 'අන්තිම කැමති පත්‍ර' (Testamentary Cases) හා භාරකාර නඩු අයත් වන්නේ කුමන නීති අංශයටද?", "සිවිල් නීතියට", "අපරාධ නීතියට", "ආරක්ෂක හමුදා නීතියට", "ජාත්‍යන්තර මානුෂීය නීතියට", "දේපළ උරුමය, භාරකාරත්වය හා අන්තිම කැමති පත්‍ර සිවිල් අධිකරණ බලය යටතේ විභාග වේ."),
    q("විධායක ජනාධිපතිවරයා විසින් කැබිනට් මණ්ඩලයේ සභාපතිත්වය දැරීමෙන් සිදුවන්නේ කුමක්ද?", "රාජ්‍යයේ හා කැබිනට් ප්‍රතිපත්තිවල ඒකාබද්ධ නායකත්වය සැලසීම", "අධිකරණයේ නඩු තීන්දු ප්‍රකාශ කිරීම", "පාර්ලිමේන්තුවේ කථානායක ධුරය දැරීම", "මැතිවරණ කොමිසමේ සභාපති වීම", "42 වන වගන්තිය අනුව ජනාධිපතිවරයා අමාත්‍ය මණ්ඩලයේ ප්‍රධානියා ලෙස ක්‍රියා කරයි."),
    q("පාර්ලිමේන්තුවේ මන්ත්‍රීවරුන් අතරින් අමාත්‍ය ධුර නොදරන මන්ත්‍රීවරුන් හඳුන්වනු ලබන්නේ කවර නමින්ද?", "පසුපෙළ මන්ත්‍රීවරුන්", "සභානායකවරුන්", "කැබිනට් ලේකම්වරුන්", "සෙනෙට් සභිකයන්", "ආණ්ඩු පක්ෂයේ හෝ විපක්ෂයේ අමාත්‍ය/නියෝජ්‍ය තනතුරු නොදරන මන්ත්‍රීවරුන් Backbenchers ලෙස හැඳින්වේ."),
    q("යුක්තිය පසිඳලීමේදී 'නීතිඥවරයෙකුගේ සහාය ලබාගැනීමේ අයිතිය' 1978 ව්‍යවස්ථාවේ කුමන වගන්තියෙන් ආරක්ෂා වී තිබේද?", "13(3) වගන්තිය", "2 වන වගන්තිය", "9 වන වගන්තිය", "78 වන වගන්තිය", "13(3) වගන්තිය අනුව වරදකට චෝදනා ලැබූ ඕනෑම අයෙකුට නීතිඥයෙකු මඟින් කරුණු දැක්වීමට අයිතිය ඇත."),
    q("ශ්‍රී ලංකාවේ 'මහාධිකරණ' සංකල්පය 1978 ව්‍යවස්ථාවේ කවර ස්ථානයක් ගනීද?", "අධිකරණ ධූරාවලියේ ඉහළම මුල් අවස්ථා අධිකරණය ලෙස", "ව්‍යවස්ථාදායකයේ උප කමිටුවක් ලෙස", "පළාත් පාලන බදු ආයතනයක් ලෙස", "පාර්ලිමේන්තු මහලේකම් කාර්යාලය ලෙස", "මහාධිකරණය බරපතළ අපරාධ හා ඇතැම් සිවිල්/වාණිජ නඩු විභාග කරන ඉහළම මුල් අවස්ථා අධිකරණයයි."),
    q("රටේ පාර්ලිමේන්තුවට තේරී පත් වූ මන්ත්‍රීවරයෙකු නොමැතිව ජනාධිපතිවරයාට රාජ්‍ය තාන්ත්‍රික සේවයට පත් කළ හැකි උසස් නිලධාරීන් කවුද?", "තානාපතිවරුන් සහ මහ කොමසාරිස්වරුන්", "පාර්ලිමේන්තු කථානායකවරුන්", "විපක්ෂ නායකවරුන්", "කෝප් කමිටු සභාපතිවරුන්", "විදේශ සබඳතා මෙහෙයවීමට තානාපතිවරුන් පත් කිරීම ජනාධිපතිවරයාගේ විධායක බලයකි."),
    q("රටේ නීතිය පනවන ව්‍යවස්ථාදායකය සහ නීතිය අර්ථනිරූපණය කරන අධිකරණය අතර පැවතිය යුතු මූලික වෙනස කුමක්ද?", "පාර්ලිමේන්තුව නීති සම්පාදනය කරන අතර අධිකරණය එම නීතිවලට අනුව ස්වාධීනව නඩු විභාග කිරීම", "අධිකරණය අයවැය ලේඛනය සම්මත කිරීම", "පාර්ලිමේන්තුව සිරදඬුවම් නියම කිරීම", "අධිකරණය මැතිවරණ පැවැත්වීම", "බලතල බෙදීම අනුව නීති සෑදීම හා නඩු තීන්දු දීම වෙන් වෙන් ආයතන මඟින් කෙරේ."),
    q("ශ්‍රී ලංකාවේ 'රජයේ ගිණුම් පිළිබඳ කාරක සභාවේ' (COPA) සභාපති ධුරය සාමාන්‍යයෙන් කුමන පාර්ශ්වයට හිමිවීම ප්‍රජාතන්ත්‍රවාදී සම්ප්‍රදායද?", "විපක්ෂයේ මන්ත්‍රීවරයෙකුට හෝ ස්වාධීනව මූල්‍ය පරීක්ෂාව කළ හැකි මන්ත්‍රීවරයෙකුට", "විදේශ තානාපතිවරයෙකුට", "අගවිනිසුරුවරයාට", "රාජ්‍ය ලේකම්වරයාට", "රජයේ වියදම් අපක්ෂපාතීව විමර්ශනය කිරීම සඳහා මෙම කමිටුවේ ස්වාධීනත්වය රැකීම වැදගත් වේ."),
    q("අධිකරණයේ 'සමථ මණ්ඩලයකට' නඩුවක් යොමු කිරීම සහ 'දිසා අධිකරණයක' නඩුවක් විභාග කිරීම අතර වෙනස කුමක්ද?", "සමථ මණ්ඩලය එකඟතාවයෙන් ආරවුල් විසඳන අතර අධිකරණය නීතියෙන් තීන්දු ප්‍රකාශ කිරීම", "සමථ මණ්ඩලය මරණ දඬුවම නියම කිරීම", "දිසා අධිකරණය පාර්ලිමේන්තු පනත් සෑදීම", "සමථ මණ්ඩලය ඉහළම අභියාචනාධිකරණය වීම", "සුළු ආරවුල් නඩු මගට නොගොස් සුහදව විසඳීමට සමථ මණ්ඩල ක්‍රියා කරයි."),
    q("පාර්ලිමේන්තු මැතිවරණයකින් පසු ජාතික ලැයිස්තු මන්ත්‍රීවරුන් 29 දෙනා පත් කරනු ලබන්නේ කුමන ආකාරයටද?", "පක්ෂ ලැබූ ජාතික ඡන්ද ප්‍රමාණයට අනුපාතිකව එම පක්ෂවල ලේකම්වරුන්ගේ නම් කිරීමෙන්", "ජනාධිපතිවරයාගේ තනි කැමැත්තෙන් පමණක්", "ශ්‍රේෂ්ඨාධිකරණ තීන්දුවකින්", "පළාත් සභා ඡන්දයෙන්", "99අ වගන්තිය අනුව පක්ෂ ලැබූ මුළු ඡන්ද අනුපාතයට ජාතික ලැයිස්තු ආසන බෙදී යයි."),
    q("රටේ පාර්ලිමේන්තුව විසින් සම්මත කරන ලද නීතියක් රටේ සියලු දෙනාටම දැනගැනීමට නිල වශයෙන් ප්‍රකාශයට පත් කරන ලේඛනය කුමක්ද?", "රජයේ ගැසට් පත්‍රය", "පාසල් වාර සටහන", "දිස්ත්‍රික් සිතියම", "වෘත්තීය සමිති පත්‍රිකාව", "නීති, පත්වීම් හා නිල නියෝග රජයේ ගැසට් පත්‍රය මඟින් ප්‍රකාශයට පත් කෙරේ."),
    q("විධායක ජනාධිපතිවරයාට පාර්ලිමේන්තුවේදී කිසියම් පනත් කෙටුම්පතක් ප්‍රතික්ෂේප කිරීමේ පූර්ණ නිෂේධ බලයක් 1978 ව්‍යවස්ථාවෙන් තිබේද?", "නැත; කථානායක සහතිකයෙන් පසු පනත නීතිගත වේ", "ඔව්; සෑම පනතක්ම තනිව අවලංගු කළ හැක", "ඔව්; පනත් කෙටුම්පත් පමණක් නොව ශ්‍රේෂ්ඨාධිකරණ තීන්දුද අවලංගු කළ හැක", "ඔව්; වසර 10ක් ප්‍රමාද කළ හැක", "ඇමරිකානු ජනාධිපතිට මෙන් ශ්‍රී ලංකාවේ ජනාධිපතිට පාර්ලිමේන්තු පනත් ප්‍රතික්ෂේප කිරීමේ නිෂේධ බලය නැත."),
    q("රජයේ පරිපාලන ක්‍රියාපටිපාටිය තුළ දිස්ත්‍රික් මට්ටමේ සංවර්ධන කටයුතු සම්බන්ධීකරණය කරන ප්‍රධාන කමිටුව කුමක්ද?", "දිස්ත්‍රික් සම්බන්ධීකරණ කමිටුව", "ශ්‍රේෂ්ඨාධිකරණ කමිටුව", "සෙනෙට් සභා කමිටුව", "ජාත්‍යන්තර ආරක්ෂක මණ්ඩලය", "දේශපාලන නායකත්වය හා රාජ්‍ය නිලධාරීන් එක්ව දිස්ත්‍රික් සංවර්ධන කටයුතු මෙහිදී සම්බන්ධීකරණය කෙරේ."),
    q("ශ්‍රී ලංකාවේ 'අධිකරණයේ මූල්‍ය හා පරිපාලන ස්වාධීනත්වය' රැකීම සඳහා විනිසුරුවරුන්ගේ වැටුප් ගෙවනු ලබන්නේ කුමන අරමුදලින්ද?", "ඒකාබද්ධ අරමුදල මත වැය බරක් ලෙස", "අමාත්‍යවරුන්ගේ පෞද්ගලික අරමුදලින්", "පළාත් පාලන බදු වලින් පමණක්", "දේශපාලන පක්ෂ අරමුදල්වලින්", "වැටුප් පාර්ලිමේන්තුවේ වාර්ෂික විවාදයකින් කප්පාදු කළ නොහැකි ලෙස ඒකාබද්ධ අරමුදලින් ගෙවනු ලැබේ."),
    q("රටේ පාර්ලිමේන්තුව හා අධිකරණය යන දෙකම ප්‍රජාතන්ත්‍රවාදයේදී එකිනෙකාට ගරු කළ යුත්තේ ඇයි?", "බලතල බෙදීමේ සමතුලිතතාව රැකගෙන නීතියේ ආධිපත්‍යය සුරැකීමට", "විධායකය සම්පූර්ණයෙන් අහෝසි කිරීමට", "මැතිවරණ පැවැත්වීම නතර කිරීමට", "රාජ්‍ය ආදායම අඩු කිරීමට", "ව්‍යවස්ථාපිත සීමාවන්ට ගරු කිරීම ප්‍රජාතන්ත්‍රවාදී ආයතනික ස්ථාවරත්වය තහවුරු කරයි."),
    q("පහත සඳහන් අංග අතරින් 'විධායකයේ' කාර්යභාරයට අයත් නොවන්නේ කුමක්ද?", "වරදකරුවන්ට සිරදඬුවම් නියම කර නඩු තීන්දු ප්‍රකාශ කිරීම", "රාජ්‍ය ප්‍රතිපත්ති ක්‍රියාත්මක කිරීම", "විදේශ තානාපති සබඳතා පවත්වාගැනීම", "ජාතික ආරක්ෂාව තහවුරු කිරීම", "නඩු විභාග කර දඬුවම් නියම කිරීම අධිකරණයේ සුවිශේෂී කාර්යයකි."),
    q("පහත සඳහන් ක්‍රියා අතරින් 'ව්‍යවස්ථාදායකයේ' කාර්යභාරයට අයත් වන්නේ කුමක්ද?", "රටට අවශ්‍ය නව පනත් සම්මත කිරීම හා රාජ්‍ය මූල්‍ය පාලනය කිරීම", "පොලිස් වරෙන්තු ක්‍රියාත්මක කිරීම", "මහාධිකරණයේ ජූරි සභාව මෙහෙයවීම", "තානාපති කාර්යාලවල වීසා නිකුත් කිරීම", "නීති සම්පාදනය හා අයවැය අනුමැතිය පාර්ලිමේන්තුවේ ප්‍රධාන වගකීම් වේ."),
    q("රටේ සෑම අධිකරණයකම විභාග වන නඩු පිළිබඳ නිල වාර්තා නිකුත් කරමින් විනිවිදභාවය රැකීමට උපකාරී වන මූලධර්මය කුමක්ද?", "විවෘත අධිකරණයේ නඩු විභාග කිරීම", "රහසිගත තීන්දු ප්‍රකාශ කිරීම", "පෞද්ගලික ඥාතීන්ට පමණක් සවන් දීම", "දේශපාලන නියෝග ක්‍රියාත්මක කිරීම", "නීතියෙන් විශේෂිතව තහනම් නොකළ සෑම නඩුවක්ම විවෘත අධිකරණයේ විභාග කිරීම යුක්තිය තහවුරු කරයි."),
    q("ශ්‍රී ලංකාවේ ළමා අපයෝජන හෝ පවුල් ගැටලු සම්බන්ධ නඩුවලදී දරුවන්ගේ පෞද්ගලිකත්වය රැකීමට අධිකරණය ගන්නා පියවර කුමක්ද?", "සංවෘත අධිකරණයේ (In Camera) නඩු විභාග කිරීම", "පුවත්පත්වල ඡායාරූප ප්‍රදර්ශනය කිරීම", "පොදු ක්‍රීඩාංගණයේ නඩු ඇසීම", "නඩුව සම්පූර්ණයෙන් ඉවත දැමීම", "ළමුන්ගේ අනන්‍යතාව හා ගෞරවය ආරක්ෂා කිරීමට සංවෘත අධිකරණ විභාග ක්‍රමය යොදා ගැනේ."),
    q("පාර්ලිමේන්තු මන්ත්‍රීවරයෙකු අඛණ්ඩව නිවාඩු ලබා නොගෙන මාස කීයක් පාර්ලිමේන්තු රැස්වීම්වලට සහභාගී නොවුණහොත් අසුන හිස් වේද?", "මාස 3 ක්", "මාස 12 ක්", "සති 2 ක්", "වසර 2 ක්", "66(ඊ) වගන්තිය අනුව පූර්ව අවසරයකින් තොරව අඛණ්ඩව මාස 3ක් නොපැමිණීමෙන් මන්ත්‍රී ධුරය හිස් වේ."),
    q("අමාත්‍ය මණ්ඩලයේ කැබිනට් සංදේශයක් (Cabinet Memorandum) ඉදිරිපත් කිරීමේ අරමුණ කුමක්ද?", "නව ප්‍රතිපත්තියක් හෝ පනතක් සඳහා කැබිනට් අනුමැතිය ලබාගැනීම", "අධිකරණ විනිසුරුවරයෙකු අත්අඩංගුවට ගැනීම", "ඡන්දදායකයන් ලියාපදිංචි කිරීම", "මැතිවරණ දිස්ත්‍රික්ක වෙනස් කිරීම", "ඇමතිවරයෙකු සිය අමාත්‍යාංශයේ යෝජනා කැබිනට් මණ්ඩලයට ඉදිරිපත් කරන්නේ කැබිනට් සංදේශයකිනි."),
    q("රටේ පාර්ලිමේන්තුවට යම් ආණ්ඩුවක වියදම් පාලනය කිරීමට ඇති ප්‍රබලම ආයුධය කුමක්ද?", "අයවැය ප්‍රතිපාදන අනුමත කිරීම හෝ ප්‍රතික්ෂේප කිරීම", "ජනාධිපති සමාව නිකුත් කිරීම", "හමුදා අභ්‍යාස පැවැත්වීම", "තානාපති කාර්යාල වැසීම", "පාර්ලිමේන්තුවේ මූල්‍ය පාලන බලය විධායකය පාලනය කිරීමේ ප්‍රධාන මඟයි."),
    q("නීතිපති දෙපාර්තමේන්තුව අපරාධ නඩුවකදී පැමිණිල්ල මෙහෙයවීමේදී පෙනී සිටින්නේ කවුරුන් වෙනුවෙන්ද?", "රාජ්‍යය හා සමස්ත මහජනතාව වෙනුවෙන්", "චූදිතයාගේ පෞද්ගලික පවුල වෙනුවෙන්", "දේශපාලන පක්ෂ කාර්යාලය වෙනුවෙන්", "පෞද්ගලික රක්ෂණ සමාගම් වෙනුවෙන්", "අපරාධ සමස්ත සමාජයට එරෙහි වැරදි ලෙස සලකන බැවින් නීතිපති රාජ්‍යය නියෝජනය කරයි."),
    q("පළාත් මට්ටමින් හෝ ප්‍රාදේශීයව ජනතාවට නීතිමය සහන පහසු කිරීම සඳහා පිහිටුවා ඇති අධිකරණ ව්‍යුහයේ ප්‍රතිලාභය කුමක්ද?", "සාමාන්‍ය ජනතාවට අඩු වියදමින් හා කඩිනමින් යුක්තිය ඉටු කර ගැනීමට හැකි වීම", "කොළඹට පමණක් නීති සීමා වීම", "නීතිඥ සේවය තහනම් වීම", "දිසා අධිකරණ සම්පූර්ණයෙන් අහෝසි වීම", "දිවයින පුරා මහේස්ත්‍රාත් හා දිසා අධිකරණ පැවතීම පුරවැසි යුක්ති ප්‍රවේශය පහසු කරයි."),
    q("විධායක ජනාධිපතිවරයෙකුට අග්‍රාමාත්‍යවරයා හෝ අමාත්‍යවරයෙකු ධුරයෙන් ඉවත් කිරීමේදී මූලිකවම අනුගමනය කළ යුතු පදනම කුමක්ද?", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ විධිවිධාන", "සමථ මණ්ඩලයේ ලිඛිත නියෝග", "පළාත් පාලන බදු වාර්තා", "විදේශ තානාපති උපදෙස්", "19 හා 21 සංශෝධන අනුව අගමැති හා කැබිනට් පත් කිරීම් හා ඉවත් කිරීම් ව්‍යවස්ථාපිත සීමාවන්ට යටත්ය."),
    q("රටක 'අධිකරණ ස්වාධීනත්වය' පවතින බව මැනිය හැකි ප්‍රධාන නිර්ණායකයක් කුමක්ද?", "විනිසුරුවරුන් දේශපාලන බලපෑම්වලින් තොරව නීතිය හා සාක්ෂි මත පමණක් තීන්දු දීම", "විනිසුරුවරුන් පාලක පක්ෂයේ රැස්වීම්වලට සහභාගී වීම", "රජයේ ඇමතිවරුන් විසින් නඩු තීන්දු ලිවීම", "පොලිස් නිලධාරීන් අධිකරණ තීන්දු අවලංගු කිරීම", "සාධාරණ විනිශ්චයක් සඳහා අධිකරණය සැමවිටම අනෙක් අංශවල පීඩනයෙන් නිදහස් විය යුතුය."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තුවේ 'සර්වජන ඡන්දයෙන් පත් වූ මන්ත්‍රීවරුන් 196' සහ 'ජාතික ලැයිස්තු 29' අතර ඇති පොදු ලක්ෂණය කුමක්ද?", "දෙපිරිසටම පාර්ලිමේන්තුවේදී සමාන මන්ත්‍රී වරප්‍රසාද හා ඡන්ද බලය හිමි වීම", "ජාතික ලැයිස්තු මන්ත්‍රීවරුන්ට ඡන්දය දීමට නොහැකි වීම", "දිස්ත්‍රික් මන්ත්‍රීවරුන්ට කැබිනට් ඇමති ධුර නොලැබීම", "ජාතික ලැයිස්තු මන්ත්‍රීවරුන්ගේ කාලය මාස 6ක් පමණක් වීම", "පත්වූ ආකාරය වෙනස් වුවද පාර්ලිමේන්තුව තුළ සියලු මන්ත්‍රීවරුන්ට සමාන අයිතීන් ඇත."),
    q("ව්‍යවස්ථාවේ 'ව්‍යවස්ථාදායක, විධායක හා අධිකරණ' අංශ අතර බලතල බෙදීම නිවැරදිව ක්‍රියාත්මක වන විට රටට ලැබෙන ප්‍රතිඵලය කුමක්ද?", "පුරවැසි නිදහස ආරක්ෂා වී ස්ථාවර ප්‍රජාතන්ත්‍රවාදී පාලනයක් පැවතීම", "රාජ්‍ය සේවය සම්පූර්ණයෙන් බිඳ වැටීම", "මැතිවරණ පැවැත්වීම අනවශ්‍ය වීම", "පළාත් සභා හා පළාත් පාලන ආයතන වැසී යාම", "බලය අයුතු ලෙස භාවිත වීම වැළැක්වී ජනතා විශ්වාසය තහවුරු වේ."),
    q("විධායක ජනාධිපතිවරයෙකු විසින් රජයේ ගැසට් පත්‍රය මඟින් පාර්ලිමේන්තුව කැඳවන විට එම සැසිවාරය විවෘත කරන්නේ කවුරුන්ද?", "විධායක ජනාධිපතිවරයා හෝ කථානායකවරයා ප්‍රමුඛ සභාව", "ශ්‍රේෂ්ඨාධිකරණ අගවිනිසුරු", "මැතිවරණ කොමසාරිස් ජනරාල්", "පළාත් ආණ්ඩුකාරවරුන්", "නව පාර්ලිමේන්තු සැසිවාරය ආරම්භයේදී කථානායක තේරීම හා ජනාධිපති ප්‍රතිපත්ති ප්‍රකාශය සිදු කෙරේ."),
    q("ශ්‍රී ලංකාවේ අධිකරණ පද්ධතියේ 'නඩු තීන්දු පූර්වාදර්ශ' (Judicial Precedents) යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "ඉහළ අධිකරණ දුන් මූලධර්ම තීන්දු පසුකාලීන සමාන නඩුවලදී පහළ අධිකරණ අනුගමනය කිරීම", "පොලිස් ස්ථානාධිපතිවරුන් දෙන නියෝග", "පළාත් සභා මන්ත්‍රීවරුන්ගේ කතා", "රේගු නිලධාරීන්ගේ දඩ කොළ", "ශ්‍රේෂ්ඨාධිකරණ හා අභියාචනාධිකරණ තීන්දු නීතිය අර්ථනිරූපණයේදී පූර්වාදර්ශ ලෙස යොදා ගැනේ."),
    q("පාර්ලිමේන්තු ක්‍රමය තුළ 'විපක්ෂය' හඳුන්වනු ලබන තවත් වැදගත් නාමයක් වන්නේ කුමක්ද?", "ආණ්ඩුවේ විකල්පය හෙවත් මුරකරුවා", "රාජ්‍ය සේවා කොමිසම", "අධිකරණ සේවා සංගමය", "විධායක කාරක සභාව", "ආණ්ඩුව අසාර්ථක වුවහොත් පාලනය භාරගැනීමට සූදානම් විකල්ප ආණ්ඩුවක් ලෙස විපක්ෂය ක්‍රියා කරයි."),
    q("රටේ ප්‍රධාන නීති කෙටුම්පත් කිරීමේදී මහජනතාවට හා සිවිල් සංවිධානවලට තම අදහස් ලබාදීමට ඇති අවස්ථාව කුමක්ද?", "කෙටුම්පත ගැසට් කළ පසු අදහස් හා පෙත්සම් ඉදිරිපත් කිරීම", "මන්ත්‍රීවරුන්ට කායිකව බාධා කිරීම", "අධිකරණ ශාලාවල උද්ඝෝෂණ කිරීම", "රාජ්‍ය ලේඛන විනාශ කිරීම", "පාර්ලිමේන්තු කාරක සභා හා ශ්‍රේෂ්ඨාධිකරණය හමුවේ නීති කෙටුම්පත් ගැන අදහස් දැක්විය හැක."),
    q("ශ්‍රී ලංකාවේ 'අධිකරණ අමාත්‍යාංශය' හා 'ස්වාධීන අධිකරණය' අතර පවතින සීමාව කුමක්ද?", "අමාත්‍යාංශය පරිපාලන පහසුකම් සපයන නමුත් නඩු තීන්දුවලට මැදිහත් නොවීම", "ඇමතිවරයා සියලු නඩු තීන්දු අනුමත කිරීම", "විනිසුරුවරුන් ඇමතිවරයාගේ ලේකම්වරුන් වීම", "අධිකරණය අමාත්‍යාංශයට දඬුවම් නියම කිරීම", "අධිකරණයේ යුක්තිය පසිඳලීම විධායකයෙන් සම්පූර්ණයෙන් ස්වාධීනව සිදු වේ."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තු රැස්වීමක් පවත්වාගෙන යාම සඳහා අවශ්‍ය අවම මන්ත්‍රී සංඛ්‍යාව හෙවත් ගණපූරණය කීයද?", "මන්ත්‍රීවරුන් 20", "මන්ත්‍රීවරුන් 50", "මන්ත්‍රීවරුන් 113", "මන්ත්‍රීවරුන් 10", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 73 වන වගන්තිය අනුව පාර්ලිමේන්තු ගණපූරණය මන්ත්‍රීවරුන් 20කි."),
    q("පාර්ලිමේන්තුවේ කථානායකවරයාගේ බලයේ හා අධිකාරියේ සංකේතය ලෙස සභා ගර්භයේ තැන්පත් කරන වස්තුව කුමක්ද?", "සෙංකෝලය (Mace)", "ජාතික ධජය", "ව්‍යවස්ථා පොත", "රාජ්‍ය මුද්‍රාව", "සෙංකෝලය තැන්පත් කර තිබීම පාර්ලිමේන්තුව නිල වශයෙන් රැස්වී ඇති බව සංකේතවත් කරයි."),
    q("පාර්ලිමේන්තු සභා ගර්භයේ සෙංකෝලය තැන්පත් කිරීම හා ආරක්ෂාව භාර ප්‍රධාන නිලධාරියා කවුද?", "වේත්‍රධාරී (Serjeant-at-Arms)", "මහ ලේකම්", "කැබිනට් ලේකම්", "විපක්ෂ සංවිධායක", "සභා ගර්භයේ විනය, ආරක්ෂාව හා සෙංකෝලය රැගෙන යාම වේත්‍රධාරීවරයාගේ රාජකාරියකි."),
    q("පාර්ලිමේන්තු විවාද සහ කතා පිළිබඳව පළ කෙරෙන නිල වාචික වාර්තාව හඳුන්වන්නේ කුමන නමින්ද?", "හැන්සාඩ් වාර්තාව (Hansard)", "රජයේ ගැසට් පත්‍රය", "විගණන වාර්තාව", "කාරක සභා සංදේශය", "පාර්ලිමේන්තු මන්ත්‍රීවරුන්ගේ සෑම කතාවක්ම හා ඡන්ද ප්‍රකාශයක්ම හැන්සාඩ් වාර්තාවේ සටහන් කෙරේ."),
    q("පාර්ලිමේන්තුව විසුරුවා හැරීමෙන් තොරව පවතින සැසිවාරය තාවකාලිකව අවසන් කිරීම හඳුන්වන්නේ කුමන නමින්ද?", "වාර අවසාන කිරීම (Prorogation)", "පාර්ලිමේන්තුව විසුරුවා හැරීම", "දෝෂාභියෝගය", "විශ්වාසභංගය", "වාර අවසාන කිරීමේදී මන්ත්‍රී ධුර අහිමි නොවී වත්මන් පාර්ලිමේන්තු සැසිවාරය පමණක් අවසන් කෙරේ."),
    q("අමාත්‍ය මණ්ඩලය කෙරෙහි පාර්ලිමේන්තුවට ඇති විශ්වාසය බිඳ වැටුණු බව පෙන්වීමට විපක්ෂය ගෙන එන යෝජනාව කුමක්ද?", "විශ්වාසභංග යෝජනාව", "පනත් කෙටුම්පත", "ශෝක යෝජනාව", "අතුරු සම්මත ගිණුම", "පාර්ලිමේන්තුවේ බහුතරයකින් විශ්වාසභංග යෝජනාවක් සම්මත වුවහොත් කැබිනට් මණ්ඩලය විසුරුවා හැරේ."),
    q("1978 ව්‍යවස්ථාව අනුව ජනාධිපතිවරයා ධුරයෙන් ඉවත් කිරීමේ දෝෂාභියෝග යෝජනාවක් අවසානයේ සම්මත විය යුත්තේ කෙසේද?", "ශ්‍රේෂ්ඨාධිකරණ පරීක්ෂණයෙන් පසු පාර්ලිමේන්තුවේ 2/3 බහුතරයෙන්", "පළාත් සභා 9යේ බහුතරයෙන්", "කැබිනට් මණ්ඩලයේ සරල බහුතරයෙන්", "මහ නගර සභා යෝජනාවකින්", "38(2) වගන්තිය අනුව චෝදනා ශ්‍රේෂ්ඨාධිකරණයෙන් විභාග කර 2/3 බහුතරයෙන් සම්මත කළ යුතුය."),
    q("පාර්ලිමේන්තුව කල් තබන අවස්ථාවක හදිසි මහජන වැදගත්කමක් ඇති කරුණක් ගැන විවාද කිරීමට ගෙන එන යෝජනාව කුමක්ද?", "සභාව කල් තැබීමේ යෝජනාව", "අයවැය විසර්ජන පනත", "ජනමත විචාරණ යෝජනාව", "දෝෂාභියෝග යෝජනාව", "කල් තැබීමේ විවාද මඟින් රටේ හදිසි සමාජ ගැටලු පාර්ලිමේන්තුව තුළ සාකච්ඡා කෙරේ."),
    q("රජයේ ඇමතිවරයෙකු හෝ නිලධාරියෙකු නීත්‍යානුකූල රාජකාරියක් ඉටු කරන ලෙස බලකරමින් අභියාචනාධිකරණය නිකුත් කරන රීට් ආඥාව කුමක්ද?", "මැන්ඩාමුස් ආඥාව (Mandamus)", "හෙබියාස් කෝපස් ආඥාව", "සර්ෂියෝරාරි ආඥාව", "තහනම් ආඥාව", "රාජ්‍ය ආයතනයකට නීතිමය රාජකාරිය ඉටු කිරීමට නියෝග කිරීමට Mandamus රීට් ආඥාව නිකුත් කෙරේ."),
    q("නීතිවිරෝධී ලෙස අත්අඩංගුවේ හෝ රැඳවුම් භාරයේ සිටින පුද්ගලයෙකු අධිකරණයට ඉදිරිපත් කරන ලෙස නියෝග කරන රීට් ආඥාව කුමක්ද?", "හෙබියාස් කෝපස් ආඥාව (Habeas Corpus)", "ක්වෝ වොරන්ටෝ ආඥාව", "මැන්ඩාමුස් ආඥාව", "සර්ෂියෝරාරි ආඥාව", "පුද්ගල නිදහස සුරැකීම සඳහා නීතිවිරෝධී රඳවා තබාගැනීම්වලට එරෙහිව Habeas Corpus ආඥාව භාවිත වේ."),
    q("අධිකරණ හෝ අර්ධ අධිකරණ ආයතනයක් නීතිමය බලය ඉක්මවා ගත් තීරණයක් අවලංගු කිරීමට නිකුත් කරන රීට් ආඥාව කුමක්ද?", "සර්ෂියෝරාරි ආඥාව (Certiorari)", "හෙබියාස් කෝපස් ආඥාව", "මැන්ඩාමුස් ආඥාව", "විශේෂ ප්‍රකාශන ආඥාව", "පහළ විනිශ්චය සභාවක වැරදි හෝ අධිකාරි බලය ඉක්මවූ තීරණයක් බලරහිත කිරීමට Certiorari නිකුත් වේ."),
    q("ශ්‍රී ලංකාවේ මුස්ලිම් විවාහ හා දික්කසාද නීතියට අදාළ පවුල් ආරවුල් විභාග කරන විශේෂ අධිකරණය කුමක්ද?", "ක්වාසි අධිකරණය", "කම්කරු විනිශ්චය සභාව", "වාණිජ මහාධිකරණය", "පරිසර අධිකරණය", "මුස්ලිම් විවාහ හා දික්කසාද පනත යටතේ පෞද්ගලික පවුල් ගැටලු ක්වාසි අධිකරණයේ විභාග කෙරේ."),
    q("සේව්‍ය සේවක ආරවුල් සහ අසාධාරණ ලෙස සේවයෙන් පහ කිරීම් පිළිබඳව පැමිණිලි විභාග කරන ආයතනය කුමක්ද?", "කම්කරු විනිශ්චය සභාව", "දිසා අධිකරණය", "මහාධිකරණය", "ශ්‍රේෂ්ඨාධිකරණය", "කාර්මික ආරවුල් පනත යටතේ සේවක අයිතිවාසිකම් රැකීමට කම්කරු විනිශ්චය සභා පිහිටුවා ඇත."),
    q("මහාධිකරණ විනිසුරුවරුන් හැර පහළ අධිකරණ විනිසුරුවරුන් පත් කිරීම හා මාරු කිරීම සිදුකරන ස්වාධීන ආයතනය කුමක්ද?", "අධිකරණ සේවා කොමිෂන් සභාව", "රාජ්‍ය සේවා කොමිෂන් සභාව", "මැතිවරණ කොමිෂන් සභාව", "පොලිස් කොමිෂන් සභාව", "අගවිනිසුරුගේ සභාපතිත්වයෙන් යුත් අධිකරණ සේවා කොමිෂන් සභාව මහේස්ත්‍රාත් හා දිසා විනිසුරුවරුන් පාලනය කරයි."),
    q("1978 ව්‍යවස්ථාවේ 34 වන වගන්තිය යටතේ වරදකරුවන්ට සමාව දීමේ විධායක බලය හිමිවන්නේ කාටද?", "ජනාධිපතිවරයාට", "අග්‍රාමාත්‍යවරයාට", "කථානායකවරයාට", "පොලිස්පතිවරයාට", "මහාධිකරණ විනිසුරුගේ හා නීතිපතිගේ වාර්තා සලකා බලා සමාව දීමේ බලය ජනාධිපතිවරයා සතුය."),
    q("ශ්‍රී ලංකාවේ මුදල් පනත් කෙටුම්පතක් පාර්ලිමේන්තුවට ඉදිරිපත් කිරීමේදී අනිවාර්යයෙන් තිබිය යුත්තේ කුමක්ද?", "අමාත්‍ය මණ්ඩලයේ අනුමැතිය", "විපක්ෂ නායකගේ අනුමැතිය", "පළාත් සභා 9යේ අනුමැතිය", "සමථ මණ්ඩලයේ නිර්දේශය", "ව්‍යවස්ථාවේ 152 වගන්තිය අනුව රාජ්‍ය මුදල් පිළිබඳ පනත් කෙටුම්පත් කැබිනට් අනුමැතියෙන් ඉදිරිපත් කළ යුතුය."),
    q("පාර්ලිමේන්තුවේ 'සභානායකවරයා' (Leader of the House) ප්‍රධාන වශයෙන් ඉටු කරන කාර්යභාරය කුමක්ද?", "පාර්ලිමේන්තුව තුළ රජයේ ව්‍යවස්ථාදායක වැඩකටයුතු හා විවාද සම්බන්ධීකරණය කිරීම", "අධිකරණ විනිසුරුවරුන් පත් කිරීම", "ඡන්ද හිමි නාමලේඛනය සැකසීම", "තානාපති කාර්යාල පවත්වාගෙන යාම", "ආණ්ඩු පක්ෂයේ පනත් කෙටුම්පත් හා සභාවේ දෛනික න්‍යාය පත්‍රය මෙහෙයවීම සභානායකගේ කාර්යයකි."),
    q("නව පනත් කෙටුම්පතක් පාර්ලිමේන්තුවට ඉදිරිපත් කර සති දෙකක් ඇතුළත ඕනෑම පුරවැසියෙකුට එහි ව්‍යවස්ථානුකූලභාවය ප්‍රශ්න කළ හැකි අධිකරණය කුමක්ද?", "ශ්‍රේෂ්ඨාධිකරණය", "මහේස්ත්‍රාත් අධිකරණය", "දිසා අධිකරණය", "කම්කරු විනිශ්චය සභාව", "121 වන වගන්තිය අනුව පනත් කෙටුම්පතක් ගැසට් කර දින 14ක් ඇතුළත ශ්‍රේෂ්ඨාධිකරණයට පෙත්සම් ගොනු කළ හැක."),
    q("පළාත් සභා සහ රාජ්‍ය ආයතන කෙරෙහි බලපාන මූල්‍ය හා කාර්ය සාධන විගණන වාර්තා පාර්ලිමේන්තුවට ඉදිරිපත් කරන ප්‍රධාන නිලධාරියා කවුද?", "විගණකාධිපතිවරයා", "මහ බැංකු අධිපතිවරයා", "රේගු අධ්‍යක්ෂ ජනරාල්වරයා", "විදේශ ලේකම්වරයා", "154 වන වගන්තිය අනුව රාජ්‍ය ගිණුම් පරීක්ෂා කර විගණකාධිපතිවරයා පාර්ලිමේන්තුවට වාර්තා කරයි."),
    q("රටේ පාර්ලිමේන්තුව සම්මත කළ පනතක් නීතියක් ලෙස බලාත්මක වීමට අවසන් වශයෙන් කුමන නිලධාරියාගේ අත්සන අවශ්‍ය වේද?", "පාර්ලිමේන්තු කථානායකවරයාගේ", "අගවිනිසුරුවරයාගේ", "මැතිවරණ කොමසාරිස්වරයාගේ", "විපක්ෂ නායකවරයාගේ", "79 වන වගන්තිය අනුව පනත් කෙටුම්පත පාර්ලිමේන්තුවෙන් සම්මත වූ බවට කථානායකවරයා සහතික කළ පසු නීතිගත වේ.")
  )
}
